create or replace function public.record_data_feature_event(p_event_type text,p_feature_code text default null,p_subject_type text default 'user',p_subject_id uuid default null,p_location_id uuid default null,p_business_id uuid default null,p_fleet_vehicle_id uuid default null,p_source_table text default null,p_source_id uuid default null,p_value_numeric numeric default null,p_value_text text default null,p_metadata jsonb default '{}'::jsonb) returns public.data_feature_events language plpgsql security definer set search_path=public as $$ declare uid uuid := auth.uid(); r public.data_feature_events; begin if uid is null then raise exception 'Authentication required'; end if; insert into public.data_feature_events(subject_type,subject_id,actor_user_id,business_id,location_id,fleet_vehicle_id,event_type,feature_code,source_table,source_id,value_numeric,value_text,metadata,occurred_at) values(p_subject_type,coalesce(p_subject_id,uid),uid,p_business_id,p_location_id,p_fleet_vehicle_id,p_event_type,p_feature_code,p_source_table,p_source_id,p_value_numeric,p_value_text,coalesce(p_metadata,'{}'::jsonb),now()) returning * into r; return r; end $$; revoke all on function public.record_data_feature_event(text,text,text,uuid,uuid,uuid,uuid,text,uuid,numeric,text,jsonb) from public; grant execute on function public.record_data_feature_event(text,text,text,uuid,uuid,uuid,uuid,text,uuid,numeric,text,jsonb) to authenticated;
create or replace function public.record_gps_checkin(p_lat double precision,p_lng double precision,p_radius_meters integer default 30) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid := auth.uid(); loc public.locations; ci public.check_ins; pts integer := 10; begin if uid is null then raise exception 'Authentication required'; end if; if p_lat is null or p_lng is null or p_lat not between -90 and 90 or p_lng not between -180 and 180 then raise exception 'Valid location required'; end if; select l.* into loc from public.locations l where l.is_active=true and l.latitude is not null and l.longitude is not null and st_dwithin(l.geom::geography,st_setsrid(st_makepoint(p_lng,p_lat),4326)::geography,least(greatest(coalesce(p_radius_meters,30),1),100)) order by st_distance(l.geom::geography,st_setsrid(st_makepoint(p_lng,p_lat),4326)::geography) limit 1; if loc.id is null then raise exception 'You must be within 100 feet of a Kleenest location to check in.'; end if; if exists(select 1 from public.check_ins x where x.user_id=uid and x.location_id=loc.id and x.checked_in_at>now()-interval '10 minutes') then raise exception 'You already checked in here recently.'; end if; insert into public.check_ins(user_id,location_id,checked_in_at,latitude,longitude,distance_meters,verification_method,points_awarded,metadata) values(uid,loc.id,now(),p_lat,p_lng,st_distance(loc.geom::geography,st_setsrid(st_makepoint(p_lng,p_lat),4326)::geography),'gps',pts,jsonb_build_object('source','home_check_in','geofence_meters',least(greatest(coalesce(p_radius_meters,30),1),100))) returning * into ci; begin perform public.record_progression_action('check_in',ci.id); exception when others then null; end; begin perform public.record_progression_metric_event('check_in','check_in',ci.id,1,pts,jsonb_build_object('verification_method','gps','location_id',loc.id)); exception when others then null; end; return jsonb_build_object('check_in',to_jsonb(ci),'location_id',loc.id,'location_name',loc.name,'points_awarded',pts,'verification_method','gps'); end $$; revoke all on function public.record_gps_checkin(double precision,double precision,integer) from public; grant execute on function public.record_gps_checkin(double precision,double precision,integer) to authenticated;
create or replace function public._kleenest_capture_feature_event() returns trigger language plpgsql security definer set search_path=public as $$ declare uid uuid; lid uuid; bid uuid; et text; fc text; md jsonb := '{}'::jsonb; sid uuid; begin if TG_TABLE_NAME='check_ins' then uid:=NEW.user_id; lid:=NEW.location_id; et:='check_in'; fc:=case when NEW.verification_method='qr' then 'qr_check_in' else 'gps_check_in' end; sid:=NEW.id; md:=jsonb_build_object('verification_method',NEW.verification_method,'distance_meters',NEW.distance_meters,'points_awarded',NEW.points_awarded); elsif TG_TABLE_NAME='reviews' then uid:=NEW.user_id; lid:=NEW.location_id; et:='review_submitted'; fc:='reviews'; sid:=NEW.id; md:=jsonb_build_object('stars',NEW.stars,'cleanliness_pct',NEW.cleanliness_pct); elsif TG_TABLE_NAME='location_photos' then uid:=NEW.user_id; lid:=NEW.location_id; et:='photo_submitted'; fc:='location_photos'; sid:=NEW.id; md:=jsonb_build_object('media_type',NEW.media_type); elsif TG_TABLE_NAME='location_amenity_observations' then uid:=NEW.user_id; lid:=NEW.location_id; et:='amenity_observed'; fc:='amenity_verification'; sid:=NEW.id; md:=jsonb_build_object('status',NEW.status,'verification_method',NEW.verification_method,'confidence',NEW.confidence); elsif TG_TABLE_NAME='review_likes' then uid:=NEW.user_id; et:='review_voted'; fc:='review_voting'; sid:=NEW.review_id; md:=jsonb_build_object('vote','like'); elsif TG_TABLE_NAME='review_amenity_feedback' then uid:=null; lid:=NEW.location_id; et:='review_amenity_feedback'; fc:='amenity_verification'; sid:=NEW.id; md:=jsonb_build_object('sentiment',NEW.sentiment,'amenity_id',NEW.amenity_id); elsif TG_TABLE_NAME='qr_redemptions' then uid:=NEW.user_id; et:='qr_redeemed'; fc:='qr_check_in'; sid:=NEW.qr_code_id; md:=jsonb_build_object('qr_code_id',NEW.qr_code_id); elsif TG_TABLE_NAME='fleet_operational_events' then et:='fleet_operation'; fc:='fleet_operations'; sid:=NEW.id; md:=jsonb_build_object('event_type',NEW.event_type,'unit',NEW.unit); end if; insert into public.data_feature_events(subject_type,subject_id,actor_user_id,business_id,location_id,fleet_vehicle_id,event_type,feature_code,source_table,source_id,value_numeric,value_text,metadata,occurred_at) values(case when lid is not null then 'location' when bid is not null then 'business' else 'user' end,coalesce(lid,bid,uid),uid,bid,lid,case when TG_TABLE_NAME='fleet_operational_events' then NEW.vehicle_id else null end,et,fc,TG_TABLE_NAME,sid,null,null,md,coalesce(NEW.created_at,NEW.occurred_at,now())); return NEW; exception when others then return NEW; end $$;
drop trigger if exists trg_capture_checkins on public.check_ins; create trigger trg_capture_checkins after insert on public.check_ins for each row execute function public._kleenest_capture_feature_event();
drop trigger if exists trg_capture_reviews on public.reviews; create trigger trg_capture_reviews after insert on public.reviews for each row execute function public._kleenest_capture_feature_event();
drop trigger if exists trg_capture_location_photos on public.location_photos; create trigger trg_capture_location_photos after insert on public.location_photos for each row execute function public._kleenest_capture_feature_event();
drop trigger if exists trg_capture_amenity_observations on public.location_amenity_observations; create trigger trg_capture_amenity_observations after insert on public.location_amenity_observations for each row execute function public._kleenest_capture_feature_event();
drop trigger if exists trg_capture_review_likes on public.review_likes; create trigger trg_capture_review_likes after insert on public.review_likes for each row execute function public._kleenest_capture_feature_event();
drop trigger if exists trg_capture_review_amenity_feedback on public.review_amenity_feedback; create trigger trg_capture_review_amenity_feedback after insert on public.review_amenity_feedback for each row execute function public._kleenest_capture_feature_event();
drop trigger if exists trg_capture_qr_redemptions on public.qr_redemptions; create trigger trg_capture_qr_redemptions after insert on public.qr_redemptions for each row execute function public._kleenest_capture_feature_event();
drop trigger if exists trg_capture_fleet_events on public.fleet_operational_events; create trigger trg_capture_fleet_events after insert on public.fleet_operational_events for each row execute function public._kleenest_capture_feature_event();
